// src/shot/theme.ts
function metrics(width) {
  const ratio = Math.max(0, Math.min(1, (width - 480) / 800));
  const round = (from2, to) => Math.round(from2 + (to - from2) * ratio);
  return {
    pad: round(22, 50),
    title: round(20, 30),
    body: round(15, 19),
    radius: round(18, 24),
    // 卡片外的画布留白：手机版几乎贴边，电脑版留出投影空间。
    outer: round(14, 40),
    brand: round(13, 15)
  };
}
function canvasPad(width) {
  return metrics(width).outer;
}

