// src/client/provider/prompt-optimize/index.ts
function applyPromptOptimize(ctx) {
  try {
    const scope = ctx;
    const models = scope.modelDirectories;
    const sessions = scope.sessions;
    scope.slots.inject("conversation.input.right", () => scope.slots.register({
      name: "conversation.input.right",
      id: "dsh-prompt-optimize",
      // 供应商标签 order 10、模型座位 order 20；本图标 order 4 位于团队按钮（order 5）左侧。
      order: 4,
      inject: (sessionId) => {
        const directory = models.directoryFor(sessionId);
        return {
          available: sessions.subagentAddress(sessionId) === void 0,
          directory: directory.store,
          // 会话 id：POST 优化请求时回传，供 host 端「显式停止」定位本次优化。
          sessionId
        };
      }
    }, PromptOptimizeButton));
  } catch (error) {
    console.warn(`[hub/prompt-optimize] \u6302\u8F7D\u5931\u8D25\uFF1A${error instanceof Error ? error.message : String(error)}`);
  }
}

// src/client/provider/index.ts
var providerClientServices = ["slots", "modelDirectories", "sessions", "remote.session"];
function guarded(label, mount) {
  try {
    mount();
  } catch (error) {
    console.warn(`[dsh-chat-plus/provider] ${label} \u6302\u8F7D\u5931\u8D25\uFF1A${error instanceof Error ? error.message : String(error)}`);
  }
}
function applyProviderClient(ctx) {
  guarded("supplier styles", () => {
    ctx.effect(() => injectStyles3(), "dsh-chat-plus: provider styles");
  });
  ctx.inject([...providerClientServices], (scope) => {
    guarded("model seats", () => applyModelSeats(scope));
    guarded("prompt optimize", () => applyPromptOptimize(scope));
  });
}

